from dataclasses import FrozenInstanceError
from decimal import Decimal

import pytest

from payment.domain.money import Money


def test_currency_is_upper_cased() -> None:
    assert Money(Decimal("1"), "eur").currency == "EUR"


def test_smallest_positive_amount_is_accepted() -> None:
    assert Money(Decimal("0.01"), "EUR").amount == Decimal("0.01")


@pytest.mark.parametrize("amount", [Decimal("0"), Decimal("-1")])
def test_non_positive_amount_is_rejected(amount: Decimal) -> None:
    with pytest.raises(ValueError, match="An amount must be positive."):
        Money(amount, "EUR")


@pytest.mark.parametrize("currency", ["", " ", "  \t"])
def test_blank_currency_is_rejected(currency: str) -> None:
    with pytest.raises(ValueError, match="A currency is required."):
        Money(Decimal("1"), currency)


def test_money_is_immutable() -> None:
    money = Money(Decimal("1"), "EUR")
    with pytest.raises(FrozenInstanceError):
        money.amount = Decimal("2")  # type: ignore[misc]


def test_money_equality_is_by_value() -> None:
    assert Money(Decimal("1"), "eur") == Money(Decimal("1"), "EUR")
EOF
cat >> tests/unit/test_authorize_payment.py <<'EOF'


class RecordingGateway:
    def __init__(self) -> None:
        self.calls: list[tuple[str, Money]] = []

    def authorize(self, reference: str, amount: Money) -> AuthorizationOutcome:
        self.calls.append((reference, amount))
        return AuthorizationOutcome.DECLINED


def test_the_gateway_receives_the_reference_and_amount() -> None:
    gateway = RecordingGateway()
    amount = Money(Decimal("5"), "EUR")

    AuthorizePayment(gateway, InMemoryReceiptStore()).handle("ORD-3", amount)

    assert gateway.calls == [("ORD-3", amount)]


def test_the_receipt_describes_amount_and_outcome() -> None:
    receipts = InMemoryReceiptStore()
    handler = AuthorizePayment(AlwaysAnswers(AuthorizationOutcome.APPROVED), receipts)

    handler.handle("ORD-4", Money(Decimal("42.50"), "eur"))

    assert receipts.saved == {"ORD-4": "EUR 42.50 -> APPROVED"}


def test_the_handler_is_final() -> None:
    assert getattr(AuthorizePayment, "__final__", False) is True
EOF
